  ('ga4.sessions', 'Sessions', 'Sessions reported by GA4.', 'SUM(sessions)', 'ga4', 'sessions', 'count', 'day', false, 'sum', array['source', 'landing_page', 'device', 'geo']::text[], null, array['GA4 reports with roughly 24 hours of delay.']::text[], 10800),
