-- --- Seed data: the scheduled digests ----------------------------------------
--
-- A digest definition belongs to a workspace, so one of each is created for
-- every workspace that already exists. The recipients are left empty: who
-- receives a digest is a decision the owner makes, not a default.

insert into public.report_definitions
  (workspace_id, key, title, description, cadence, sections, formats, recipients, enabled)
select
  w.id,
  s.key,
  s.title,
  s.description,
  s.cadence,
  s.sections,
  s.formats,
  '{}'::text[],
  s.enabled
from public.workspaces w
cross join (
  values
    ('daily-performance', 'Daily performance digest', 'The previous day''s paid, organic and search performance, with the connections that were not reporting.', 'daily', '["ads","ga4","gsc","alerts","connections"]'::jsonb::jsonb, array['csv']::text[], true),
    ('weekly-performance', 'Weekly performance digest', 'The last seven days across the whole site portfolio, with the campaigns that moved the most.', 'weekly', '["ads","ga4","gsc","alerts","connections"]'::jsonb::jsonb, array['csv']::text[], true),
    ('monthly-performance', 'Monthly performance digest', 'The last thirty days, for the monthly review of spend, traffic and search.', 'monthly', '["ads","ga4","gsc","alerts","connections"]'::jsonb::jsonb, array['csv']::text[], true)
) as s(key, title, description, cadence, sections, formats, enabled)
on conflict (workspace_id, key) do update
  set title = excluded.title,
      description = excluded.description,
      cadence = excluded.cadence,
      sections = excluded.sections,
      formats = excluded.formats,
      updated_at = now();

-- --- Row Level Security policies ---------------------------------------------

-- Every table is protected. The helper functions decide what each role may
-- read, and the account-scoped roles additionally need an explicit grant.


-- --- Owner controlled workspace creation -----------------------------------

create or replace function public.create_workspace_for_owner(p_name text)
returns table (id uuid, name text)
language plpgsql
security definer
set search_path = public
as $$
declare
  actor uuid := auth.uid();
  workspace_id uuid;
  workspace_name text := trim(p_name);
  workspace_slug text;
begin
  if actor is null then
    raise exception 'Authentication required' using errcode = '42501';
  end if;
  if workspace_name is null or length(workspace_name) < 2 or length(workspace_name) > 80 then
    raise exception 'Workspace name must be between 2 and 80 characters' using errcode = '22023';
  end if;
  if not exists (
    select 1 from public.workspace_members m
    where m.user_id = actor and m.status = 'active' and m.role = 'owner'
  ) then
    raise exception 'Only a workspace owner can create workspaces' using errcode = '42501';
  end if;

  workspace_slug := trim(both '-' from regexp_replace(lower(workspace_name), '[^a-z0-9]+', '-', 'g'));
  if workspace_slug = '' then workspace_slug := 'workspace'; end if;
  workspace_slug := left(workspace_slug, 48) || '-' || left(replace(gen_random_uuid()::text, '-', ''), 10);

  insert into public.workspaces (name, slug)
  values (workspace_name, workspace_slug)
  returning workspaces.id into workspace_id;

  insert into public.workspace_members (workspace_id, user_id, role, status)
  values (workspace_id, actor, 'owner', 'active');

  return query select workspace_id, workspace_name;
end;
$$;

revoke all on function public.create_workspace_for_owner(text) from public;
revoke all on function public.create_workspace_for_owner(text) from anon;
grant execute on function public.create_workspace_for_owner(text) to authenticated;

-- --- Table privileges --------------------------------------------------------
-- --- The job-kind enum ------------------------------------------------------
--
-- The application enqueues job kinds the enum must have. It is recreated
-- when a kind is missing, and only then: `ALTER TYPE ... ADD VALUE` cannot
-- be run inside a function and cannot be undone, so the column is moved to
-- text, the type is replaced, and the column is moved back.
--
-- The list comes from src/lib/jobs/kinds.ts, which is the same list the
-- handler registry uses.

do $$
declare
  v_missing text;
begin
  select string_agg(e.enumlabel, ', ')
    into v_missing
  from pg_type t
  join pg_enum e on e.enumtypid = t.oid
  where t.typname = 'sync_job_kind'
    and t.typnamespace = 'public'::regnamespace
    and e.enumlabel not in ('ga4.sessions', 'ga4.events', 'gsc.query', 'ads.campaign', 'ads.search_terms', 'gtm.inventory', 'pagespeed.run', 'uptime.check', 'social.snapshot', 'social.posts', 'rank.snapshot', 'mail.sync', 'site.crawl', 'alerts.evaluate', 'retention.prune', 'reports.generate');

  if v_missing is not null then
    alter table public.sync_jobs alter column kind type text;
    drop type if exists public.sync_job_kind;
    create type public.sync_job_kind as enum ('ga4.sessions', 'ga4.events', 'gsc.query', 'ads.campaign', 'ads.search_terms', 'gtm.inventory', 'pagespeed.run', 'uptime.check', 'social.snapshot', 'social.posts', 'rank.snapshot', 'mail.sync', 'site.crawl', 'alerts.evaluate', 'retention.prune', 'reports.generate');
    alter table public.sync_jobs
      alter column kind type public.sync_job_kind
      using kind::public.sync_job_kind;
  end if;
end
$$;

