-- --- Table privileges --------------------------------------------------------
--
-- The policies above decide *which rows* the authenticated role may see.
-- These grants give it the *table* privileges the policies need. They are
-- derived from the policy list, so a table with no policy for a command
-- gets no privilege for it.
--
-- provider_connection_credentials is deliberately absent: it has a policy
-- that denies every authenticated role, and no privilege is granted either.
-- Only the service role — the sync worker — may read it.
-- Account login credential and access-ticket tables are likewise absent:
-- only server routes with an explicit launch permission may use them.

grant usage on schema public to authenticated;
grant select on public.account_launch_profiles to authenticated;
grant insert on public.account_launch_profiles to authenticated;
grant update on public.account_launch_profiles to authenticated;
grant delete on public.account_launch_profiles to authenticated;
grant select on public.action_item_events to authenticated;
grant insert on public.action_item_events to authenticated;
grant select on public.action_items to authenticated;
grant insert on public.action_items to authenticated;
grant update on public.action_items to authenticated;
grant delete on public.action_items to authenticated;
grant select on public.ai_insight_requests to authenticated;
grant insert on public.ai_insight_requests to authenticated;
grant select on public.ai_insight_sources to authenticated;
